import sourced from "./tourismSites.json";

// What there is to see in Bénin, and where each fact came from.
//
// The screen used to list five landmarks written from memory. Five is not a
// country, and "everything in Bénin" cannot be recalled — only sourced. So
// this file has two halves, and they are kept apart on purpose:
//
//   - tourismSites.json, regenerated by scripts/fetchTourismSites.js from
//     Wikidata: coordinates, the type, the heritage listing, the French
//     Wikipedia article, and a Commons photograph with its licence and
//     photographer. Nothing in it is typed by hand, so re-running the
//     script cannot quietly lose a correction.
//   - HAND_ENTERED below, for the places Wikidata has nothing usable for.
//     Each one says why it is here rather than there.
//
// What this file does NOT carry: entry prices, opening hours, guide fees
// and telephone numbers. Nothing publishes them in a form worth trusting,
// they change, and a visitor who drives four hours on a stale opening time
// has been failed by the app rather than by the site. The screen says so
// where the design asks for a figure — the same rule the OpenStreetMap
// tier follows on the hotels screen.
import { distanceInKm } from "../utils/geo";
import { compareNames } from "../utils/collate";

// Places Wikidata cannot supply.
//
// The Route des Pêches is the case that proves the point: it is the thing
// people name second after Ganvié, and its Wikidata item is an empty stub
// — no coordinates, no type, no photograph, not even a country. Typing
// cannot reach it and neither can a photo fetch. So it is written out
// here, with a coordinate that is the road itself rather than a building,
// and no photograph at all rather than a picture of some other beach.
const HAND_ENTERED = [
  {
    id: "hand-route-des-peches",
    name: "Route des Pêches",
    nameEn: "Route des Pêches",
    // The coast road between Cotonou and Ouidah. The point given is the
    // middle of the stretch, near Avlékété, because a 40 km road has no
    // single address and the nearest end would flatter the drive time.
    latitude: 6.3479,
    longitude: 2.2361,
    admin: "Cotonou — Ouidah",
    types: ["route côtière", "plage"],
    heritage: [],
    article: null,
    photo: null,
    tier: "hand",
    // What is actually along it, said plainly. The bars and restaurants on
    // this road are real and they are also the app's own business: rather
    // than name places nobody here has verified, the card sends the reader
    // to the Restaurants screen, which lists establishments that put
    // themselves there.
    alongKey: "restaurants",
  },
];

// Wikidata's types are precise and there are seventy of them. A reader
// choosing what to do today wants six. The mapping is by word, in the
// order below, because a "palais royal" is history before it is
// architecture and a "réserve de biosphère" is nature before it is a park.
const CATEGORY_RULES = [
  { key: "nature", words: ["parc national", "réserve", "aire protégée", "forêt", "bois sacré", "zone humide", "marécage", "jardin", "parc", "montagne", "massif", "chaîne", "grotte", "lac", "lagune", "fleuve", "rivière", "site Ramsar", "afforestation", "climate"] },
  { key: "beach", words: ["plage", "route côtière"] },
  { key: "heritage", words: ["palais", "site archéologique", "forteresse", "paysage culturel", "patrimoine", "stèle", "navire"] },
  { key: "museum", words: ["musée", "fondation", "centre culturel", "laboratoire", "résidence"] },
  { key: "worship", words: ["cathédrale", "basilique", "mosquée", "temple", "vaudou", "sanctuaire", "pèlerinage", "église"] },
  { key: "memory", words: ["mémorial", "monument", "statue", "sculpture", "fontaine", "place"] },
  { key: "town", words: ["commune", "ville", "établissement humain", "marché", "bâtiment"] },
];

export function categoryOf(site) {
  const types = (site.types ?? []).map((type) => type.toLowerCase());
  for (const rule of CATEGORY_RULES) {
    if (types.some((type) => rule.words.some((word) => type.includes(word)))) {
      return rule.key;
    }
  }
  return "town";
}

// A world heritage site is a different proposition from a listed façade,
// and the badge should not flatten them together.
export function heritageRank(site) {
  const all = (site.heritage ?? []).join(" ").toLowerCase();
  if (all.includes("patrimoine mondial") && !all.includes("indicative")) return 3;
  if (all.includes("indicative")) return 2;
  if (all.includes("ramsar") || all.includes("biosphère")) return 1;
  return all ? 1 : 0;
}

export const tourismSites = [...sourced, ...HAND_ENTERED]
  .map((site) => ({ ...site, category: categoryOf(site) }))
  .sort((a, b) => compareNames(a.name, b.name));

export const tourismPhotoCount = tourismSites.filter((site) => site.photo).length;

// Distance as the crow flies, which is not a drive time and is not
// presented as one — see the screen, where the band is named in hours by
// road and this only orders the list.
export function withDistance(sites, coords) {
  if (!coords) return sites.map((site) => ({ ...site, distanceKm: null }));
  return sites.map((site) => ({
    ...site,
    distanceKm: distanceInKm(coords, site),
  }));
}

// How long it takes to get there, and why that is a band and not a number.
//
// The design's organising idea is "how long have you got", which only works
// if a site's distance is expressed in driving hours from where the reader
// actually is: the Pendjari is a nine-hour expedition from Cotonou and a
// morning out from Natitingou, and one list cannot describe both.
//
// The hours come from the design document's own origin×region matrix. They
// are estimates by road and are labelled as such on screen — a road here
// is not a constant, and the state of the pistes in the north changes what
// the same distance costs. What is NOT done is dressing a straight-line
// distance up as a drive time, which would be precise and wrong: 130 km of
// coast road and 130 km of Atacora track are not the same afternoon.
export const tourismOrigins = [
  { key: "cotonou", label: "Cotonou", sub: "Littoral", latitude: 6.3703, longitude: 2.3912 },
  { key: "calavi", label: "Abomey-Calavi", sub: "Atlantique", latitude: 6.4489, longitude: 2.3556 },
  { key: "portonovo", label: "Porto-Novo", sub: "Ouémé", latitude: 6.4969, longitude: 2.6289 },
  { key: "bohicon", label: "Bohicon / Abomey", sub: "Zou", latitude: 7.1782, longitude: 2.0667 },
  { key: "parakou", label: "Parakou", sub: "Borgou", latitude: 9.3372, longitude: 2.6303 },
  { key: "natitingou", label: "Natitingou", sub: "Atacora", latitude: 10.3042, longitude: 1.3796 },
];

// The eight zones the matrix is written in, each with a point to measure
// against. A site is assigned to the nearest one, so the mapping is
// computed from its coordinates rather than typed out 125 times — and a
// site added tomorrow gets a zone without anybody remembering to give it
// one.
const ZONES = [
  { key: "cotonou", latitude: 6.3703, longitude: 2.3912 },
  { key: "ouidah", latitude: 6.3667, longitude: 2.0833 },
  { key: "portonovo", latitude: 6.4969, longitude: 2.6289 },
  { key: "abomey", latitude: 7.1856, longitude: 1.9911 },
  { key: "mono", latitude: 6.2833, longitude: 1.8167 },
  { key: "couffo", latitude: 6.9333, longitude: 1.7833 },
  { key: "atacora", latitude: 10.3042, longitude: 1.3796 },
  { key: "alibori", latitude: 11.1342, longitude: 2.9386 },
];

const HOURS = {
  cotonou: { cotonou: 0.4, ouidah: 1.5, portonovo: 0.8, abomey: 2.5, mono: 2, couffo: 2.5, atacora: 8, alibori: 10 },
  calavi: { cotonou: 0.5, ouidah: 1, portonovo: 1.3, abomey: 2.3, mono: 1.8, couffo: 2.3, atacora: 7.8, alibori: 9.8 },
  portonovo: { cotonou: 0.8, ouidah: 2, portonovo: 0.3, abomey: 2.5, mono: 2.8, couffo: 2.8, atacora: 8, alibori: 10 },
  bohicon: { cotonou: 2.3, ouidah: 2.5, portonovo: 2.5, abomey: 0.4, mono: 2.5, couffo: 1.5, atacora: 5.5, alibori: 7.5 },
  parakou: { cotonou: 6, ouidah: 7, portonovo: 6.5, abomey: 4, mono: 7, couffo: 5.5, atacora: 2.5, alibori: 3 },
  natitingou: { cotonou: 8, ouidah: 9, portonovo: 8.5, abomey: 5.5, mono: 8.5, couffo: 7, atacora: 0.4, alibori: 3 },
};

export function zoneOf(site) {
  let best = ZONES[0];
  let bestKm = Infinity;
  ZONES.forEach((zone) => {
    const km = distanceInKm(site, zone);
    if (km < bestKm) {
      bestKm = km;
      best = zone;
    }
  });
  return best.key;
}

export function driveHours(site, originKey) {
  return HOURS[originKey]?.[zoneOf(site)] ?? null;
}

// Under an hour is an afternoon, up to three is a day, beyond that is a
// weekend. The thresholds are the design's.
export const tourismBands = [
  { key: "proche", maxHours: 1 },
  { key: "journee", maxHours: 3 },
  { key: "weekend", maxHours: Infinity },
];

export function bandOf(hours) {
  if (hours == null) return null;
  if (hours < 1) return "proche";
  if (hours <= 3) return "journee";
  return "weekend";
}
